class MicroVMError(Exception):
    """Base exception for all microvm errors."""
    pass


class LexError(MicroVMError):
    """Raised when tokenization fails."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset = offset


class ParseError(MicroVMError):
    """Raised when parsing fails."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset = offset


class CompileError(MicroVMError):
    """Raised when compilation fails (e.g., duplicate declaration, undeclared name)."""
    pass


class SerializationError(MicroVMError):
    """Raised on malformed binary data or serialization issues."""
    pass


class VMRuntimeError(MicroVMError):
    """Raised when a runtime error occurs during execution."""
    pass


class StepLimitError(VMRuntimeError):
    """Raised when the step limit is exceeded."""
    pass

OPCODES: tuple[str, ...] = (
    "CONST", "LOAD", "STORE", "ADD", "SUB", "MUL", "DIV", "MOD", "NEG", "NOT",
    "EQ", "NE", "LT", "LE", "GT", "GE", "JUMP", "JUMP_IF_FALSE", "PRINT", "POP", "HALT",
)

OPCODE_NUMBERS: dict[str, int] = {name: index + 1 for index, name in enumerate(OPCODES)}

import dataclasses
import re

from microvm.errors import LexError

_TOKEN_PATTERNS: list[tuple[str, str]] = [
    ("STRING", r'"([^"\\]*(?:\\.?[^"\\]*)*)"'),
    ("FLOAT", r'\d+\.\d+(?:[eE][+-]?\d+)?'),
    ("INT", r'\d+'),
    ("IDENT", r'[A-Za-z_][A-Za-z0-9_]*'),
    ("OP", r'==|!=|<=|>=|[+\-*/%(){};=<>]'),
]

_ESCAPE_MAP = {"n": "\n", "t": "\t", '"': '"', "\\": "\\"}

_KEYWORDS = {
    "let", "print", "if", "else", "while", "true", "false", "and", "or", "not",
}


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str
    text: str
    value: object
    offset: int


def _decode_string(raw: str) -> str:
    chars: list[str] = []
    i = 0
    while i < len(raw):
        if raw[i] == "\\":
            if i + 1 >= len(raw):
                raise ValueError  # shouldn't happen
            ch = raw[i + 1]
            if ch in _ESCAPE_MAP:
                chars.append(_ESCAPE_MAP[ch])
            else:
                raise LexError(f"Invalid escape sequence: \\{ch}", 0)
            i += 2
        else:
            chars.append(raw[i])
            i += 1
    return "".join(chars)


def tokenize(src: str) -> list[Token]:
    tokens: list[Token] = []
    pos = 0
    while pos < len(src):
        ch = src[pos]
        if ch in " \t\r\n":
            pos += 1
            continue
        if ch == "/" and pos + 1 < len(src) and src[pos + 1] == "/":
            end = src.find("\n", pos)
            if end == -1:
                break
            pos = end + 1
            continue

        matched = False
        for kind, pattern in _TOKEN_PATTERNS:
            m = re.match(pattern, src, pos)
            if m is not None and m.start() == pos:
                raw = m.group(0)
                if kind == "STRING":
                    inner = raw[1:-1]
                    value = _decode_string(inner)
                    tokens.append(Token("STRING", value, value, pos))
                elif kind == "FLOAT":
                    tokens.append(Token("FLOAT", raw, float(raw), pos))
                elif kind == "INT":
                    tokens.append(Token("INT", raw, int(raw), pos))
                elif kind == "IDENT":
                    text = raw
                    if text in _KEYWORDS:
                        tokens.append(Token("KEYWORD", text, text, pos))
                    else:
                        tokens.append(Token("IDENT", text, text, pos))
                else:
                    tokens.append(Token(kind, raw, raw, pos))
                pos = m.end()
                matched = True
                break

        if not matched:
            raise LexError(f"Unexpected character: {ch!r}", pos)

    return tokens

from microvm.errors import ParseError, LexError
from microvm.lexer import tokenize, Token

# AST node types


class ASTNode:
    """Base class for all AST nodes."""
    pass


class ProgramNode(ASTNode):
    __slots__ = ("statements",)

    def __init__(self, statements: list) -> None:
        self.statements = statements


class LetNode(ASTNode):
    __slots__ = ("name", "value", "offset")

    def __init__(self, name: str, value: object, offset: int) -> None:
        self.name = name
        self.value = value
        self.offset = offset


class AssignNode(ASTNode):
    __slots__ = ("name", "value", "offset")

    def __init__(self, name: str, value: object, offset: int) -> None:
        self.name = name
        self.value = value
        self.offset = offset


class PrintNode(ASTNode):
    __slots__ = ("value",)

    def __init__(self, value: object) -> None:
        self.value = value


class IfNode(ASTNode):
    __slots__ = ("condition", "then_branch", "else_branch")

    def __init__(self, condition: object, then_branch: object, else_branch: object | None) -> None:
        self.condition = condition
        self.then_branch = then_branch
        self.else_branch = else_branch


class WhileNode(ASTNode):
    __slots__ = ("condition", "body")

    def __init__(self, condition: object, body: object) -> None:
        self.condition = condition
        self.body = body


class BlockNode(ASTNode):
    __slots__ = ("statements",)

    def __init__(self, statements: list) -> None:
        self.statements = statements


class BinaryOpNode(ASTNode):
    __slots__ = ("op", "left", "right", "offset")

    def __init__(self, op: str, left: object, right: object, offset: int) -> None:
        self.op = op
        self.left = left
        self.right = right
        self.offset = offset


class UnaryOpNode(ASTNode):
    __slots__ = ("op", "operand", "offset")

    def __init__(self, op: str, operand: object, offset: int) -> None:
        self.op = op
        self.operand = operand
        self.offset = offset


class LiteralNode(ASTNode):
    __slots__ = ("value",)

    def __init__(self, value: object) -> None:
        self.value = value


class IdentNode(ASTNode):
    __slots__ = ("name", "offset")

    def __init__(self, name: str, offset: int) -> None:
        self.name = name
        self.offset = offset


class Parser:
    def __init__(self, tokens: list[Token]) -> None:
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind: str, text: str | None = None) -> Token:
        tok = self.peek()
        if tok is None:
            offset = self.tokens[-1].offset + len(self.tokens[-1].text) if self.tokens else 0
            raise ParseError(f"Expected {kind} '{text}', got end of input", offset)
        if tok.kind != kind or (text is not None and tok.text != text):
            raise ParseError(f"Expected {kind} '{text}', got {tok.kind} '{tok.text}'", tok.offset)
        return self.advance()

    def match(self, kind: str, text: str | None = None) -> bool:
        tok = self.peek()
        if tok is None:
            return False
        if tok.kind != kind:
            return False
        if text is not None and tok.text != text:
            return False
        return True

    def parse(self) -> ProgramNode:
        statements: list[object] = []
        while self.peek() is not None:
            stmt = self.parse_statement()
            if stmt is not None:
                statements.append(stmt)
        return ProgramNode(statements)

    def parse_statement(self) -> object | None:
        tok = self.peek()
        if tok is None:
            return None
        if tok.kind == "KEYWORD":
            if tok.text == "let":
                return self.parse_let()
            elif tok.text == "print":
                return self.parse_print()
            elif tok.text == "if":
                return self.parse_if()
            elif tok.text == "while":
                return self.parse_while()
        if tok.text == "{":
            return self.parse_block()
        return self.parse_assign()

    def parse_let(self) -> LetNode:
        self.expect("KEYWORD", "let")
        name_tok = self.expect("IDENT")
        self.expect("OP", "=")
        value = self.parse_expr()
        self.expect("OP", ";")
        return LetNode(name_tok.text, value, name_tok.offset)

    def parse_assign(self) -> AssignNode:
        name_tok = self.expect("IDENT")
        if self.match("OP", "="):
            self.advance()
            value = self.parse_expr()
            self.expect("OP", ";")
            return AssignNode(name_tok.text, value, name_tok.offset)
        # It might be a bare expression? The language only allows let/assign/print/if/while/block
        # But if we see IDENT not followed by =, it's a parse error at the IDENT
        # Actually the spec says statements are: let, assignment, print, if, while, block
        # So IDENT must be followed by =
        raise ParseError(f"Expected '=' after identifier '{name_tok.text}'", name_tok.offset)

    def parse_print(self) -> PrintNode:
        self.expect("KEYWORD", "print")
        value = self.parse_expr()
        self.expect("OP", ";")
        return PrintNode(value)

    def parse_if(self) -> IfNode:
        tok = self.expect("KEYWORD", "if")
        self.expect("OP", "(")
        condition = self.parse_expr()
        self.expect("OP", ")")
        then_branch = self.parse_statement() or BlockNode([])
        else_branch: object | None = None
        if self.match("KEYWORD", "else"):
            self.advance()
            else_branch = self.parse_statement() or BlockNode([])
        return IfNode(condition, then_branch, else_branch)

    def parse_while(self) -> WhileNode:
        self.expect("KEYWORD", "while")
        self.expect("OP", "(")
        condition = self.parse_expr()
        self.expect("OP", ")")
        body = self.parse_statement() or BlockNode([])
        return WhileNode(condition, body)

    def parse_block(self) -> BlockNode:
        self.expect("OP", "{")
        statements: list[object] = []
        while self.peek() is not None and not self.match("OP", "}"):
            stmt = self.parse_statement()
            if stmt is not None:
                statements.append(stmt)
        self.expect("OP", "}")
        return BlockNode(statements)

    # Expression parsing

    def parse_expr(self) -> object:
        return self.parse_or()

    def parse_or(self) -> object:
        left = self.parse_and()
        while self.match("KEYWORD", "or"):
            tok = self.advance()
            right = self.parse_and()
            left = BinaryOpNode("or", left, right, tok.offset)
        return left

    def parse_and(self) -> object:
        left = self.parse_not()
        while self.match("KEYWORD", "and"):
            tok = self.advance()
            right = self.parse_not()
            left = BinaryOpNode("and", left, right, tok.offset)
        return left

    def parse_not(self) -> object:
        if self.match("KEYWORD", "not"):
            tok = self.advance()
            operand = self.parse_not()
            return UnaryOpNode("not", operand, tok.offset)
        return self.parse_comparison()

    def parse_comparison(self) -> object:
        left = self.parse_additive()
        if self.match("OP") and self.peek() and self.peek().text in ("==", "!=", "<", "<=", ">", ">="):
            op_tok = self.advance()
            right = self.parse_additive()
            return BinaryOpNode(op_tok.text, left, right, op_tok.offset)
        return left

    def parse_additive(self) -> object:
        left = self.parse_multiplicative()
        while self.match("OP") and self.peek() and self.peek().text in ("+", "-"):
            op_tok = self.advance()
            right = self.parse_multiplicative()
            left = BinaryOpNode(op_tok.text, left, right, op_tok.offset)
        return left

    def parse_multiplicative(self) -> object:
        left = self.parse_unary()
        while self.match("OP") and self.peek() and self.peek().text in ("*", "/", "%"):
            op_tok = self.advance()
            right = self.parse_unary()
            left = BinaryOpNode(op_tok.text, left, right, op_tok.offset)
        return left

    def parse_unary(self) -> object:
        if self.match("OP") and self.peek() and self.peek().text == "-":
            tok = self.advance()
            operand = self.parse_unary()
            return UnaryOpNode("-", operand, tok.offset)
        return self.parse_primary()

    def parse_primary(self) -> object:
        tok = self.peek()
        if tok is None:
            raise ParseError("Expected expression, got end of input",
                             self.tokens[-1].offset + len(self.tokens[-1].text))
        if tok.kind == "INT":
            self.advance()
            return LiteralNode(tok.value)
        if tok.kind == "FLOAT":
            self.advance()
            return LiteralNode(tok.value)
        if tok.kind == "STRING":
            self.advance()
            return LiteralNode(tok.value)
        if tok.kind == "KEYWORD" and tok.text == "true":
            self.advance()
            return LiteralNode(True)
        if tok.kind == "KEYWORD" and tok.text == "false":
            self.advance()
            return LiteralNode(False)
        if tok.kind == "IDENT":
            self.advance()
            return IdentNode(tok.text, tok.offset)
        if tok.text == "(":
            self.advance()
            expr = self.parse_expr()
            self.expect("OP", ")")
            return expr
        raise ParseError(f"Unexpected token: {tok.kind} '{tok.text}'", tok.offset)


def parse(src: str) -> object:
    try:
        tokens = tokenize(src)
    except LexError:
        raise
    parser = Parser(tokens)
    return parser.parse()

import dataclasses
from typing import Any

from microvm.opcodes import OPCODES, OPCODE_NUMBERS
from microvm.parser import (
    parse, ProgramNode, LetNode, AssignNode, PrintNode, IfNode,
    WhileNode, BlockNode, BinaryOpNode, UnaryOpNode, LiteralNode, IdentNode,
)
from microvm.errors import CompileError


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str
    arg: int | None


@dataclasses.dataclass
class Program:
    constants: list
    names: list[str]
    instructions: list


class Compiler:
    def __init__(self, optimize: bool = False) -> None:
        self.constants: list[Any] = []
        self.const_map: dict[tuple, int] = {}
        self.names: list[str] = []
        self.name_slots: dict[str, int] = {}
        self.declared: set[str] = set()
        self.instructions: list[Instr] = []
        self.next_label = 0
        self.optimize = optimize

    def add_constant(self, value: Any) -> int:
        key = (type(value).__name__, value)
        idx = self.const_map.get(key)
        if idx is not None:
            return idx
        idx = len(self.constants)
        self.constants.append(value)
        self.const_map[key] = idx
        return idx

    def get_name_slot(self, name: str) -> int:
        slot = self.name_slots.get(name)
        if slot is not None:
            return slot
        slot = len(self.names)
        self.names.append(name)
        self.name_slots[name] = slot
        return slot

    def declare_name(self, name: str, offset: int) -> int:
        if name in self.declared:
            raise CompileError(f"Duplicate declaration of '{name}'")
        self.declared.add(name)
        return self.get_name_slot(name)

    def fresh_label(self) -> int:
        lbl = self.next_label
        self.next_label += 1
        return lbl

    def emit(self, op: str, arg: int | None = None) -> None:
        self.instructions.append(Instr(op, arg))

    def patch_jump(self, instr_index: int) -> None:
        self.instructions[instr_index] = Instr(
            self.instructions[instr_index].op, len(self.instructions)
        )

    def compile_node(self, node: object) -> None:
        if isinstance(node, ProgramNode):
            for stmt in node.statements:
                self.compile_node(stmt)
            self.emit("HALT")
        elif isinstance(node, LetNode):
            slot = self.declare_name(node.name, node.offset)
            self.compile_node(node.value)
            self.emit("STORE", slot)
        elif isinstance(node, AssignNode):
            if node.name not in self.declared:
                raise CompileError(f"Undeclared variable '{node.name}'")
            slot = self.name_slots[node.name]
            self.compile_node(node.value)
            self.emit("STORE", slot)
        elif isinstance(node, PrintNode):
            self.compile_node(node.value)
            self.emit("PRINT")
        elif isinstance(node, IfNode):
            else_label = self.fresh_label()
            end_label = self.fresh_label()
            self.compile_node(node.condition)
            self.emit("JUMP_IF_FALSE", else_label)
            self.compile_node(node.then_branch)
            self.emit("JUMP", end_label)
            # Patch else_label to point here
            self._patch_later(else_label)
            if node.else_branch is not None:
                self.compile_node(node.else_branch)
            self._patch_later(end_label)
        elif isinstance(node, WhileNode):
            cond_label = len(self.instructions)
            self.compile_node(node.condition)
            self.emit("JUMP_IF_FALSE", 0)  # placeholder
            false_jump = len(self.instructions) - 1
            self.compile_node(node.body)
            self.emit("JUMP", cond_label)
            self.patch_jump(false_jump)
        elif isinstance(node, BlockNode):
            for stmt in node.statements:
                self.compile_node(stmt)
        elif isinstance(node, BinaryOpNode):
            if node.op == "and":
                self._compile_and(node)
            elif node.op == "or":
                self._compile_or(node)
            elif node.op in ("+", "-", "*", "/", "%", "==", "!=", "<", "<=", ">", ">="):
                self.compile_node(node.left)
                self.compile_node(node.right)
                op_map = {
                    "+": "ADD", "-": "SUB", "*": "MUL", "/": "DIV", "%": "MOD",
                    "==": "EQ", "!=": "NE", "<": "LT", "<=": "LE", ">": "GT", ">=": "GE",
                }
                self.emit(op_map[node.op])
        elif isinstance(node, UnaryOpNode):
            if node.op == "not":
                self.compile_node(node.operand)
                self.emit("NOT")
            elif node.op == "-":
                self.compile_node(node.operand)
                self.emit("NEG")
        elif isinstance(node, LiteralNode):
            idx = self.add_constant(node.value)
            self.emit("CONST", idx)
        elif isinstance(node, IdentNode):
            if node.name not in self.declared:
                raise CompileError(f"Undeclared variable '{node.name}'")
            slot = self.name_slots[node.name]
            self.emit("LOAD", slot)

    def _compile_and(self, node: BinaryOpNode) -> None:
        """Short-circuit: left && right - only eval right if left is true."""
        false_label = self.fresh_label()
        end_label = self.fresh_label()
        self.compile_node(node.left)
        self.emit("JUMP_IF_FALSE", false_label)
        self.emit("POP")
        self.compile_node(node.right)
        self.emit("JUMP", end_label)
        self._patch_later(false_label)
        false_idx = self.add_constant(False)
        self.emit("CONST", false_idx)
        self._patch_later(end_label)

    def _compile_or(self, node: BinaryOpNode) -> None:
        """Short-circuit: left || right - only eval right if left is false."""
        right_label = self.fresh_label()
        end_label = self.fresh_label()
        self.compile_node(node.left)
        self.emit("JUMP_IF_FALSE", right_label)
        # left was true, result is true
        self.emit("POP")
        true_idx = self.add_constant(True)
        self.emit("CONST", true_idx)
        self.emit("JUMP", end_label)
        self._patch_later(right_label)
        self.emit("POP")
        self.compile_node(node.right)
        self._patch_later(end_label)

    def _patch_later(self, label_id: int) -> None:
        # Store placeholder with negative label id
        self.instructions.append(Instr("__FIX__", -label_id - 1))

    def fix_labels(self) -> None:
        """Resolve label placeholders, inlining into instructions list."""
        # Build label -> instruction index mapping
        pending: dict[int, list[int]] = {}
        final_instrs: list[Instr] = []
        for idx, instr in enumerate(self.instructions):
            if instr.op == "__FIX__":
                lbl = -instr.arg - 1
                pending.setdefault(lbl, []).append(idx)
            else:
                final_instrs.append(instr)
        # Now rebuild with correct jumps
        # We need to map original instruction indices to new indices
        # Since we're removing __FIX__ entries, indices shift
        old_to_new: dict[int, int] = {}
        new_idx = 0
        for old_idx, instr in enumerate(self.instructions):
            if instr.op == "__FIX__":
                continue
            old_to_new[old_idx] = new_idx
            new_idx += 1
        # Now patch all jumps
        for i, instr in enumerate(final_instrs):
            if instr.op in ("JUMP", "JUMP_IF_FALSE") and instr.arg is not None:
                # arg could be a label or a direct index
                if instr.arg < 0:
                    # It's actually a label placeholder from _patch_later
                    pass  # handled below
            if instr.op == "JUMP_IF_FALSE" and instr.arg is not None:
                # Check if arg is a label (negative)
                if instr.arg < 0:
                    lbl = -instr.arg - 1
                    # Find the target instruction index among the pending list
                    target_old = pending.get(lbl, [0])[0]
                    target_new = old_to_new.get(target_old, 0)
                    final_instrs[i] = Instr(instr.op, target_new)
            if instr.op == "JUMP" and instr.arg is not None:
                if instr.arg < 0:
                    lbl = -instr.arg - 1
                    target_old = pending.get(lbl, [0])[0]
                    target_new = old_to_new.get(target_old, 0)
                    final_instrs[i] = Instr(instr.op, target_new)
        self.instructions = final_instrs

    def _resolve_labels(self) -> None:
        """Alternative: patch labels in-place on self.instructions."""
        # Map label -> instruction index
        label_positions: dict[int, int] = {}
        i = 0
        while i < len(self.instructions):
            instr = self.instructions[i]
            if instr.op == "__FIX__":
                lbl = -instr.arg - 1
                label_positions[lbl] = i
            i += 1
        # Remove __FIX__ entries and update instruction list
        new_instructions: list[Instr] = []
        removed = 0
        old_to_new: dict[int, int] = {}
        for i, instr in enumerate(self.instructions):
            if instr.op == "__FIX__":
                lbl = -instr.arg - 1
                # The target is this index in the final list
                label_positions[lbl] = len(new_instructions)
                removed += 1
            else:
                old_to_new[i] = len(new_instructions)
                new_instructions.append(instr)
        # Now patch jumps
        for i, instr in enumerate(new_instructions):
            if instr.op in ("JUMP", "JUMP_IF_FALSE") and instr.arg is not None:
                # arg could be a label (negative) or already a target index from patch_jump
                if instr.arg < 0:
                    lbl = -instr.arg - 1
                    target = label_positions.get(lbl, 0)
                    new_instructions[i] = Instr(instr.op, target)
                # else it's already a valid index from patch_jump
        self.instructions = new_instructions


def compile_source(src: str, *, optimize: bool = False) -> Program:
    from microvm.optimizer import fold_constants
    ast = parse(src)
    if optimize:
        ast = fold_constants(ast)
    compiler = Compiler()
    compiler.compile_node(ast)
    compiler._resolve_labels()
    return Program(
        constants=list(compiler.constants),
        names=list(compiler.names),
        instructions=list(compiler.instructions),
    )

import dataclasses
from typing import Any

from microvm.opcodes import OPCODES, OPCODE_NUMBERS
from microvm.parser import (
    parse, ProgramNode, LetNode, AssignNode, PrintNode, IfNode,
    WhileNode, BlockNode, BinaryOpNode, UnaryOpNode, LiteralNode, IdentNode,
)
from microvm.errors import CompileError


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str
    arg: int | None


@dataclasses.dataclass
class Program:
    constants: list
    names: list[str]
    instructions: list


class Compiler:
    def __init__(self, optimize: bool = False) -> None:
        self.constants: list[Any] = []
        self.const_map: dict[tuple, int] = {}
        self.names: list[str] = []
        self.name_slots: dict[str, int] = {}
        self.declared: set[str] = set()
        self.instructions: list[Instr] = []
        self.pending_labels: dict[int, list[int]] = {}
        self.label_positions: dict[int, int] = {}
        self.next_label = 0
        self.optimize = optimize

    def add_constant(self, value: Any) -> int:
        key = (type(value).__name__, value)
        idx = self.const_map.get(key)
        if idx is not None:
            return idx
        idx = len(self.constants)
        self.constants.append(value)
        self.const_map[key] = idx
        return idx

    def get_name_slot(self, name: str) -> int:
        slot = self.name_slots.get(name)
        if slot is not None:
            return slot
        slot = len(self.names)
        self.names.append(name)
        self.name_slots[name] = slot
        return slot

    def declare_name(self, name: str, offset: int) -> int:
        if name in self.declared:
            raise CompileError(f"Duplicate declaration of '{name}'")
        self.declared.add(name)
        return self.get_name_slot(name)

    def fresh_label(self) -> int:
        lbl = self.next_label
        self.next_label += 1
        return lbl

    def emit(self, op: str, arg: int | None = None) -> None:
        self.instructions.append(Instr(op, arg))

    def emit_jump(self, op: str, label: int) -> None:
        """Emit a JUMP or JUMP_IF_FALSE with a label (resolved later)."""
        idx = len(self.instructions)
        self.instructions.append(Instr(op, -label - 1))  # negative sentinel
        self.pending_labels.setdefault(label, []).append(idx)

    def mark_label(self, label: int) -> None:
        """Record that `label` points to the current instruction index."""
        self.label_positions[label] = len(self.instructions)

    def emit_jump_here(self, op: str) -> None:
        """Emit a JUMP/JUMP_IF_FALSE that jumps to the *next* instruction (used for patching)."""
        self.instructions.append(Instr(op, len(self.instructions) + 1))

    def compile_node(self, node: object) -> None:
        if isinstance(node, ProgramNode):
            for stmt in node.statements:
                self.compile_node(stmt)
            self.emit("HALT")
        elif isinstance(node, LetNode):
            slot = self.declare_name(node.name, node.offset)
            self.compile_node(node.value)
            self.emit("STORE", slot)
        elif isinstance(node, AssignNode):
            if node.name not in self.declared:
                raise CompileError(f"Undeclared variable '{node.name}'")
            slot = self.name_slots[node.name]
            self.compile_node(node.value)
            self.emit("STORE", slot)
        elif isinstance(node, PrintNode):
            self.compile_node(node.value)
            self.emit("PRINT")
        elif isinstance(node, IfNode):
            else_label = self.fresh_label()
            end_label = self.fresh_label()
            self.compile_node(node.condition)
            self.emit_jump("JUMP_IF_FALSE", else_label)
            self.compile_node(node.then_branch)
            self.emit_jump("JUMP", end_label)
            self.mark_label(else_label)
            if node.else_branch is not None:
                self.compile_node(node.else_branch)
            self.mark_label(end_label)
        elif isinstance(node, WhileNode):
            cond_label = self.fresh_label()
            end_label = self.fresh_label()
            self.mark_label(cond_label)
            self.compile_node(node.condition)
            self.emit_jump("JUMP_IF_FALSE", end_label)
            self.compile_node(node.body)
            self.emit_jump("JUMP", cond_label)
            self.mark_label(end_label)
        elif isinstance(node, BlockNode):
            for stmt in node.statements:
                self.compile_node(stmt)
        elif isinstance(node, BinaryOpNode):
            if node.op == "and":
                self._compile_and(node)
            elif node.op == "or":
                self._compile_or(node)
            else:
                self.compile_node(node.left)
                self.compile_node(node.right)
                op_map = {
                    "+": "ADD", "-": "SUB", "*": "MUL", "/": "DIV", "%": "MOD",
                    "==": "EQ", "!=": "NE", "<": "LT", "<=": "LE", ">": "GT", ">=": "GE",
                }
                self.emit(op_map[node.op])
        elif isinstance(node, UnaryOpNode):
            if node.op == "not":
                self.compile_node(node.operand)
                self.emit("NOT")
            elif node.op == "-":
                self.compile_node(node.operand)
                self.emit("NEG")
        elif isinstance(node, LiteralNode):
            idx = self.add_constant(node.value)
            self.emit("CONST", idx)
        elif isinstance(node, IdentNode):
            if node.name not in self.declared:
                raise CompileError(f"Undeclared variable '{node.name}'")
            slot = self.name_slots[node.name]
            self.emit("LOAD", slot)

    def _compile_and(self, node: BinaryOpNode) -> None:
        false_label = self.fresh_label()
        end_label = self.fresh_label()
        self.compile_node(node.left)
        self.emit_jump("JUMP_IF_FALSE", false_label)
        self.emit("POP")
        self.compile_node(node.right)
        self.emit_jump("JUMP", end_label)
        self.mark_label(false_label)
        # Push False as result (left was false)
        fidx = self.add_constant(False)
        self.emit("CONST", fidx)
        self.mark_label(end_label)

    def _compile_or(self, node: BinaryOpNode) -> None:
        right_label = self.fresh_label()
        end_label = self.fresh_label()
        self.compile_node(node.left)
        self.emit_jump("JUMP_IF_FALSE", right_label)
        # Left was true -> push true, skip right
        self.emit("POP")
        tidx = self.add_constant(True)
        self.emit("CONST", tidx)
        self.emit_jump("JUMP", end_label)
        self.mark_label(right_label)
        # Left was false -> evaluate right
        self.emit("POP")
        self.compile_node(node.right)
        self.mark_label(end_label)

    def resolve_labels(self) -> None:
        """Replace label sentinels with actual instruction indices."""
        for label, instr_indices in self.pending_labels.items():
            target = self.label_positions.get(label)
            if target is None:
                continue
            for idx in instr_indices:
                instr = self.instructions[idx]
                self.instructions[idx] = Instr(instr.op, target)


def compile_source(src: str, *, optimize: bool = False) -> Program:
    from microvm.optimizer import fold_constants
    ast = parse(src)
    if optimize:
        ast = fold_constants(ast)
    compiler = Compiler()
    compiler.compile_node(ast)
    compiler.resolve_labels()
    return Program(
        constants=list(compiler.constants),
        names=list(compiler.names),
        instructions=list(compiler.instructions),
    )

import dataclasses
from typing import Any

from microvm.parser import (
    parse, ProgramNode, LetNode, AssignNode, PrintNode, IfNode,
    WhileNode, BlockNode, BinaryOpNode, UnaryOpNode, LiteralNode, IdentNode,
)
from microvm.errors import CompileError


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str
    arg: int | None


@dataclasses.dataclass
class Program:
    constants: list
    names: list[str]
    instructions: list


class Compiler:
    def __init__(self, optimize: bool = False) -> None:
        self.constants: list[Any] = []
        self.const_map: dict[tuple, int] = {}
        self.names: list[str] = []
        self.name_slots: dict[str, int] = {}
        self.declared: set[str] = set()
        self.instructions: list[Instr] = []
        self.pending_labels: dict[int, list[int]] = {}
        self.label_positions: dict[int, int] = {}
        self.next_label = 0
        self.optimize = optimize

    def add_constant(self, value: Any) -> int:
        key = (type(value).__name__, value)
        idx = self.const_map.get(key)
        if idx is not None:
            return idx
        idx = len(self.constants)
        self.constants.append(value)
        self.const_map[key] = idx
        return idx

    def get_name_slot(self, name: str) -> int:
        slot = self.name_slots.get(name)
        if slot is not None:
            return slot
        slot = len(self.names)
        self.names.append(name)
        self.name_slots[name] = slot
        return slot

    def declare_name(self, name: str, offset: int) -> int:
        if name in self.declared:
            raise CompileError(f"Duplicate declaration of '{name}'")
        self.declared.add(name)
        return self.get_name_slot(name)

    def fresh_label(self) -> int:
        lbl = self.next_label
        self.next_label += 1
        return lbl

    def emit(self, op: str, arg: int | None = None) -> None:
        self.instructions.append(Instr(op, arg))

    def emit_jump(self, op: str, label: int) -> None:
        idx = len(self.instructions)
        self.instructions.append(Instr(op, -label - 1))
        self.pending_labels.setdefault(label, []).append(idx)

    def mark_label(self, label: int) -> None:
        self.label_positions[label] = len(self.instructions)

    def compile_node(self, node: object) -> None:
        if isinstance(node, ProgramNode):
            for stmt in node.statements:
                self.compile_node(stmt)
            self.emit("HALT")
        elif isinstance(node, LetNode):
            slot = self.declare_name(node.name, node.offset)
            self.compile_node(node.value)
            self.emit("STORE", slot)
        elif isinstance(node, AssignNode):
            if node.name not in self.declared:
                raise CompileError(f"Undeclared variable '{node.name}'")
            slot = self.name_slots[node.name]
            self.compile_node(node.value)
            self.emit("STORE", slot)
        elif isinstance(node, PrintNode):
            self.compile_node(node.value)
            self.emit("PRINT")
        elif isinstance(node, IfNode):
            else_label = self.fresh_label()
            end_label = self.fresh_label()
            self.compile_node(node.condition)
            self.emit_jump("JUMP_IF_FALSE", else_label)
            self.compile_node(node.then_branch)
            self.emit_jump("JUMP", end_label)
            self.mark_label(else_label)
            if node.else_branch is not None:
                self.compile_node(node.else_branch)
            self.mark_label(end_label)
        elif isinstance(node, WhileNode):
            cond_label = self.fresh_label()
            end_label = self.fresh_label()
            self.mark_label(cond_label)
            self.compile_node(node.condition)
            self.emit_jump("JUMP_IF_FALSE", end_label)
            self.compile_node(node.body)
            self.emit_jump("JUMP", cond_label)
            self.mark_label(end_label)
        elif isinstance(node, BlockNode):
            for stmt in node.statements:
                self.compile_node(stmt)
        elif isinstance(node, BinaryOpNode):
            if node.op == "and":
                self._compile_and(node)
            elif node.op == "or":
                self._compile_or(node)
            else:
                self.compile_node(node.left)
                self.compile_node(node.right)
                op_map = {
                    "+": "ADD", "-": "SUB", "*": "MUL", "/": "DIV", "%": "MOD",
                    "==": "EQ", "!=": "NE", "<": "LT", "<=": "LE", ">": "GT", ">=": "GE",
                }
                self.emit(op_map[node.op])
        elif isinstance(node, UnaryOpNode):
            if node.op == "not":
                self.compile_node(node.operand)
                self.emit("NOT")
            elif node.op == "-":
                self.compile_node(node.operand)
                self.emit("NEG")
        elif isinstance(node, LiteralNode):
            idx = self.add_constant(node.value)
            self.emit("CONST", idx)
        elif isinstance(node, IdentNode):
            if node.name not in self.declared:
                raise CompileError(f"Undeclared variable '{node.name}'")
            slot = self.name_slots[node.name]
            self.emit("LOAD", slot)

    def _compile_and(self, node: BinaryOpNode) -> None:
        false_label = self.fresh_label()
        end_label = self.fresh_label()
        self.compile_node(node.left)
        self.emit_jump("JUMP_IF_FALSE", false_label)
        self.emit("POP")
        self.compile_node(node.right)
        self.emit_jump("JUMP", end_label)
        self.mark_label(false_label)
        fidx = self.add_constant(False)
        self.emit("CONST", fidx)
        self.mark_label(end_label)

    def _compile_or(self, node: BinaryOpNode) -> None:
        right_label = self.fresh_label()
        end_label = self.fresh_label()
        self.compile_node(node.left)
        self.emit_jump("JUMP_IF_FALSE", right_label)
        self.emit("POP")
        tidx = self.add_constant(True)
        self.emit("CONST", tidx)
        self.emit_jump("JUMP", end_label)
        self.mark_label(right_label)
        self.emit("POP")
        self.compile_node(node.right)
        self.mark_label(end_label)

    def resolve_labels(self) -> None:
        for label, instr_indices in self.pending_labels.items():
            target = self.label_positions.get(label)
            if target is None:
                continue
            for idx in instr_indices:
                instr = self.instructions[idx]
                self.instructions[idx] = Instr(instr.op, target)


def compile_source(src: str, *, optimize: bool = False) -> Program:
    from microvm.optimizer import fold_constants
    ast = parse(src)
    if optimize:
        ast = fold_constants(ast)
    compiler = Compiler()
    compiler.compile_node(ast)
    compiler.resolve_labels()
    return Program(
        constants=list(compiler.constants),
        names=list(compiler.names),
        instructions=list(compiler.instructions),
    )

from microvm.parser import (
    ProgramNode, LetNode, AssignNode, PrintNode, IfNode,
    WhileNode, BlockNode, BinaryOpNode, UnaryOpNode, LiteralNode, IdentNode,
)


def _is_bool_literal(node: object) -> bool:
    return isinstance(node, LiteralNode) and isinstance(node.value, bool)


def fold_constants(node: object) -> object:
    if isinstance(node, ProgramNode):
        return ProgramNode([fold_constants(s) for s in node.statements])
    elif isinstance(node, LetNode):
        return LetNode(node.name, fold_constants(node.value), node.offset)
    elif isinstance(node, AssignNode):
        return AssignNode(node.name, fold_constants(node.value), node.offset)
    elif isinstance(node, PrintNode):
        return PrintNode(fold_constants(node.value))
    elif isinstance(node, IfNode):
        cond = fold_constants(node.condition)
        then_branch = fold_constants(node.then_branch)
        else_branch = fold_constants(node.else_branch) if node.else_branch is not None else None
        return IfNode(cond, then_branch, else_branch)
    elif isinstance(node, WhileNode):
        return WhileNode(fold_constants(node.condition), fold_constants(node.body))
    elif isinstance(node, BlockNode):
        return BlockNode([fold_constants(s) for s in node.statements])
    elif isinstance(node, BinaryOpNode):
        left = fold_constants(node.left)
        right = fold_constants(node.right)
        left_lit = isinstance(left, LiteralNode)
        right_lit = isinstance(right, LiteralNode)

        # and/or short-circuit folding
        if node.op == "and":
            if _is_bool_literal(left):
                if left.value is False:
                    # false and X -> false
                    return LiteralNode(False)
                # true and X -> must NOT fold (still checks X is BOOL at runtime)
                if _is_bool_literal(right):
                    return LiteralNode(right.value)
                return BinaryOpNode("and", left, right, node.offset)
            if _is_bool_literal(right):
                if right.value is False:
                    # X and false -> only if X is also bool literal (handled above)
                    # For non-literal X, can't fold
                    pass
            return BinaryOpNode("and", left, right, node.offset)
        elif node.op == "or":
            if _is_bool_literal(left):
                if left.value is True:
                    # true or X -> true
                    return LiteralNode(True)
                # false or X -> must NOT fold (still checks X is BOOL at runtime)
                if _is_bool_literal(right):
                    return LiteralNode(right.value)
                return BinaryOpNode("or", left, right, node.offset)
            return BinaryOpNode("or", left, right, node.offset)

        if not left_lit or not right_lit:
            return BinaryOpNode(node.op, left, right, node.offset)

        lv = left.value
        rv = right.value

        try:
            result = _fold_binary(node.op, lv, rv)
            if result is not None:
                return LiteralNode(result)
        except Exception:
            pass
        return BinaryOpNode(node.op, left, right, node.offset)

    elif isinstance(node, UnaryOpNode):
        operand = fold_constants(node.operand)
        if isinstance(operand, LiteralNode):
            try:
                result = _fold_unary(node.op, operand.value)
                if result is not None:
                    return LiteralNode(result)
            except Exception:
                pass
        return UnaryOpNode(node.op, operand, node.offset)
    elif isinstance(node, (LiteralNode, IdentNode)):
        return node
    return node


def _fold_binary(op: str, lv: object, rv: object) -> object | None:
    if op in ("+", "-", "*"):
        if isinstance(lv, bool) or isinstance(rv, bool):
            return None  # bools not allowed in arithmetic
        if isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
            if op == "+":
                return lv + rv  # type: ignore
            elif op == "-":
                return lv - rv  # type: ignore
            elif op == "*":
                return lv * rv  # type: ignore
        if op == "+" and isinstance(lv, str) and isinstance(rv, str):
            return lv + rv
        return None
    elif op == "/":
        if isinstance(lv, bool) or isinstance(rv, bool):
            return None
        if isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
            if rv == 0:
                return None  # don't fold division by zero
            return lv / rv  # type: ignore
        return None
    elif op == "%":
        if isinstance(lv, bool) or isinstance(rv, bool):
            return None
        if isinstance(lv, int) and isinstance(rv, int):
            if rv == 0:
                return None
            return lv % rv
        return None
    elif op in ("==", "!="):
        # == and != never raise; cross-type returns False (or True for !=)
        if isinstance(lv, bool) and isinstance(rv, bool):
            eq = lv == rv
        elif isinstance(lv, bool) or isinstance(rv, bool):
            # BOOL vs non-BOOL: not equal
            eq = False
        elif isinstance(lv, str) and isinstance(rv, str):
            eq = lv == rv
        elif isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
            eq = lv == rv  # type: ignore
        else:
            eq = False
        if op == "==":
            return eq
        else:
            return not eq
    elif op in ("<", "<=", ">", ">="):
        if isinstance(lv, bool) or isinstance(rv, bool):
            return None  # would raise at runtime
        if isinstance(lv, str) and isinstance(rv, str):
            if op == "<":
                return lv < rv
            elif op == "<=":
                return lv <= rv
            elif op == ">":
                return lv > rv
            elif op == ">=":
                return lv >= rv
            return None
        if isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
            if op == "<":
                return lv < rv  # type: ignore
            elif op == "<=":
                return lv <= rv  # type: ignore
            elif op == ">":
                return lv > rv  # type: ignore
            elif op == ">=":
                return lv >= rv  # type: ignore
        return None
    return None


def _fold_unary(op: str, v: object) -> object | None:
    if op == "not":
        if isinstance(v, bool):
            return not v
        return None  # not on non-bool would raise at runtime
    elif op == "-":
        if isinstance(v, bool):
            return None  # - on bool would raise
        if isinstance(v, (int, float)):
            return -v
        return None
    return None

from microvm.errors import VMRuntimeError, StepLimitError
from microvm.opcodes import OPCODES, OPCODE_NUMBERS
from microvm.compiler import Program, Instr


def _check_num(val: object, context: str = "") -> None:
    """Raise VMRuntimeError if val is a bool or not a number/string."""
    if isinstance(val, bool):
        raise VMRuntimeError(f"Type error: BOOL not allowed in {context}")


def _fmt_bool(val: bool) -> str:
    return "true" if val else "false"


def execute(program: Program, *, step_limit: int = 100_000) -> list[str]:
    if isinstance(step_limit, bool) or not isinstance(step_limit, int):
        raise ValueError("step_limit must be a positive int")
    if step_limit <= 0:
        raise ValueError("step_limit must be a positive int")

    constants = program.constants
    names = program.names
    instrs = program.instructions
    # Variables: each is (initialized, value)
    slots: list[tuple[bool, object]] = [(False, None) for _ in names]

    stack: list[object] = []
    ip = 0
    steps = 0
    output: list[str] = []

    while ip < len(instrs):
        steps += 1
        if steps > step_limit:
            raise StepLimitError(f"Step limit {step_limit} exceeded")

        instr = instrs[ip]
        op = instr.op
        arg = instr.arg

        if op == "HALT":
            break
        elif op == "CONST":
            assert arg is not None
            stack.append(constants[arg])
        elif op == "LOAD":
            assert arg is not None
            init, val = slots[arg]
            if not init:
                raise VMRuntimeError(f"Variable '{names[arg]}' declared but never assigned")
            stack.append(val)
        elif op == "STORE":
            assert arg is not None
            val = stack.pop()
            slots[arg] = (True, val)
        elif op == "ADD":
            r = stack.pop()
            l = stack.pop()
            if isinstance(l, str) and isinstance(r, str):
                stack.append(l + r)
            elif isinstance(l, bool) or isinstance(r, bool):
                raise VMRuntimeError("Type error: + on BOOL")
            elif isinstance(l, str) or isinstance(r, str):
                raise VMRuntimeError("Type error: + requires both numbers or both strings")
            else:
                stack.append(l + r)  # type: ignore
        elif op == "SUB":
            r = stack.pop()
            l = stack.pop()
            _check_num(l, "SUB")
            _check_num(r, "SUB")
            stack.append(l - r)  # type: ignore
        elif op == "MUL":
            r = stack.pop()
            l = stack.pop()
            _check_num(l, "MUL")
            _check_num(r, "MUL")
            stack.append(l * r)  # type: ignore
        elif op == "DIV":
            r = stack.pop()
            l = stack.pop()
            _check_num(l, "DIV")
            _check_num(r, "DIV")
            if r == 0:
                raise VMRuntimeError("Division by zero")
            # / always yields FLOAT
            stack.append(l / r)  # type: ignore
        elif op == "MOD":
            r = stack.pop()
            l = stack.pop()
            _check_num(l, "MOD")
            _check_num(r, "MOD")
            if not isinstance(l, int) or not isinstance(r, int):
                raise VMRuntimeError("Type error: % requires INT operands")
            if r == 0:
                raise VMRuntimeError("Modulo by zero")
            stack.append(l % r)
        elif op == "NEG":
            v = stack.pop()
            _check_num(v, "NEG")
            stack.append(-v)  # type: ignore
        elif op == "NOT":
            v = stack.pop()
            if not isinstance(v, bool):
                raise VMRuntimeError("Type error: NOT requires BOOL")
            stack.append(not v)
        elif op == "EQ":
            r = stack.pop()
            l = stack.pop()
            stack.append(_eq_impl(l, r))
        elif op == "NE":
            r = stack.pop()
            l = stack.pop()
            stack.append(not _eq_impl(l, r))
        elif op == "LT":
            r = stack.pop()
            l = stack.pop()
            stack.append(_cmp_impl(l, r, "<"))
        elif op == "LE":
            r = stack.pop()
            l = stack.pop()
            stack.append(_cmp_impl(l, r, "<="))
        elif op == "GT":
            r = stack.pop()
            l = stack.pop()
            stack.append(_cmp_impl(l, r, ">"))
        elif op == "GE":
            r = stack.pop()
            l = stack.pop()
            stack.append(_cmp_impl(l, r, ">="))
        elif op == "JUMP":
            assert arg is not None
            ip = arg
            continue
        elif op == "JUMP_IF_FALSE":
            assert arg is not None
            cond = stack.pop()
            if not isinstance(cond, bool):
                raise VMRuntimeError("Type error: condition must be BOOL")
            if not cond:
                ip = arg
                continue
        elif op == "PRINT":
            val = stack.pop()
            if isinstance(val, bool):
                output.append(_fmt_bool(val))
            elif isinstance(val, float):
                output.append(str(val))
            else:
                output.append(str(val))
        elif op == "POP":
            stack.pop()

        ip += 1

    return output


def _eq_impl(l: object, r: object) -> bool:
    """Equality per spec: cross-type false except numeric."""
    if isinstance(l, bool) and isinstance(r, bool):
        return l == r
    if isinstance(l, bool) or isinstance(r, bool):
        return False
    if isinstance(l, str) and isinstance(r, str):
        return l == r
    if isinstance(l, (int, float)) and isinstance(r, (int, float)):
        return l == r  # type: ignore
    return False


def _cmp_impl(l: object, r: object, op: str) -> bool:
    """Comparison per spec: two numbers or two strings."""
    if isinstance(l, bool) or isinstance(r, bool):
        raise VMRuntimeError(f"Type error: comparison on BOOL")
    if isinstance(l, str) and isinstance(r, str):
        if op == "<":
            return l < r
        elif op == "<=":
            return l <= r
        elif op == ">":
            return l > r
        elif op == ">=":
            return l >= r
    if isinstance(l, (int, float)) and isinstance(r, (int, float)):
        if op == "<":
            return l < r  # type: ignore
        elif op == "<=":
            return l <= r  # type: ignore
        elif op == ">":
            return l > r  # type: ignore
        elif op == ">=":
            return l >= r  # type: ignore
    raise VMRuntimeError(f"Type error: cannot compare {type(l).__name__} with {type(r).__name__}")

from microvm.compiler import Program


def _escape_str(s: str) -> str:
    """Escape a string for disassembly: \n, \t, \", \\."""
    result = s.replace("\\", "\\\\")
    result = result.replace("\n", "\\n")
    result = result.replace("\t", "\\t")
    result = result.replace('"', '\\"')
    return result


def _format_const(val: object) -> str:
    if isinstance(val, bool):
        return "true" if val else "false"
    if isinstance(val, float):
        return str(val)
    if isinstance(val, str):
        return f'"{_escape_str(val)}"'
    return str(val)


def disassemble(program: Program) -> str:
    lines: list[str] = []
    for idx, instr in enumerate(program.instructions):
        op = instr.op
        arg = instr.arg
        prefix = f"{idx:04d} {op}"
        if arg is not None:
            if op == "CONST":
                val = program.constants[arg]
                lines.append(f"{prefix} {arg}  ; {_format_const(val)}\n")
            else:
                lines.append(f"{prefix} {arg}\n")
        else:
            lines.append(f"{prefix}\n")
    return "".join(lines)

